import{_ as t,P as n,I as r,g as o,d as l,k as e,l as i,j as p}from"./chunks/framework.CjoWWfVe.js";const f=JSON.parse('{"title":"Калькулятор себестоимости онлайн: расчёт изделия из кожи и шаблон Excel","description":"Бесплатный онлайн-калькулятор расчёта себестоимости продукции и изделий для мастеров и цехов. Формула расчёта себестоимости, оцифровка обрезков кожи, ставка нормы-часа и шаблон таблицы Excel.","frontmatter":{"title":"Калькулятор себестоимости онлайн: расчёт изделия из кожи и шаблон Excel","description":"Бесплатный онлайн-калькулятор расчёта себестоимости продукции и изделий для мастеров и цехов. Формула расчёта себестоимости, оцифровка обрезков кожи, ставка нормы-часа и шаблон таблицы Excel.","tags":["Инструменты","Экономика","Кожевенное дело"]},"headers":[],"relativePath":"ru/articles/leather-cost-calculator.md","filePath":"ru/articles/leather-cost-calculator.md"}'),c={name:"ru/articles/leather-cost-calculator.md"};function d(h,a,g,u,x,b){const s=n("CostCalculator");return r(),o("div",null,[a[0]||(a[0]=l("div",{class:"article-breadcrumb"},[l("a",{href:"/ru/articles/"},"← Все статьи и гайды")],-1)),a[1]||(a[1]=l("h1",{id:"калькулятор-себестоимости-онлаин-расчет-изделия-из-кожи-ловушка-обрезков-и-формула-стоимости-продукции",tabindex:"-1"},[e("Калькулятор себестоимости онлайн: расчёт изделия из кожи, ловушка обрезков и формула стоимости продукции "),l("a",{class:"header-anchor",href:"#калькулятор-себестоимости-онлаин-расчет-изделия-из-кожи-ловушка-обрезков-и-формула-стоимости-продукции","aria-label":'Permalink to "Калькулятор себестоимости онлайн: расчёт изделия из кожи, ловушка обрезков и формула стоимости продукции"'},"​")],-1)),a[2]||(a[2]=l("p",null,"Бесплатный онлайн-калькулятор расчёта себестоимости продукции для кожевенников, мастеров ручного труда и ремесленных мастерских. Рассчитайте точную себестоимость изделия за одну минуту: выберите типовое изделие или введите свои параметры. Калькулятор мгновенно учитывает скрытые потери сырья в обрезках, стоимость нормы-часа мастера и износ инструмента.",-1)),i(s,{lang:"ru"}),a[3]||(a[3]=p(`<hr><h2 id="🚦-диагноз-заказа-как-читать-результат-расчета" tabindex="-1">🚦 Диагноз заказа: как читать результат расчёта <a class="header-anchor" href="#🚦-диагноз-заказа-как-читать-результат-расчета" aria-label="Permalink to &quot;🚦 Диагноз заказа: как читать результат расчёта&quot;">​</a></h2><p>Калькулятор делит любой заказ на три чёткие зоны:</p><h3 id="🔴-1-иллюзия-прибыли-заказ-убыточен" tabindex="-1">🔴 1. Иллюзия прибыли (Заказ убыточен) <a class="header-anchor" href="#🔴-1-иллюзия-прибыли-заказ-убыточен" aria-label="Permalink to &quot;🔴 1. Иллюзия прибыли (Заказ убыточен)&quot;">​</a></h3><p>Полная себестоимость изделия (материалы + труд + износ инструмента) превышает розничную цену.</p><ul><li><strong>Что происходит:</strong> мастер работает бесплатно и доплачивает клиенту своими деньгами за покупку материалов.</li><li><strong>Что делать:</strong> срочно повышать цену, оптимизировать лекала для уменьшения расхода кожи или отказываться от нерентабельной модели.</li></ul><h3 id="🟡-2-скрытыи-риск-недооценка-трудоемкости" tabindex="-1">🟡 2. Скрытый риск (Недооценка трудоёмкости) <a class="header-anchor" href="#🟡-2-скрытыи-риск-недооценка-трудоемкости" aria-label="Permalink to &quot;🟡 2. Скрытый риск (Недооценка трудоёмкости)&quot;">​</a></h3><p>Формально заказ закрылся с небольшим плюсом, но фактическая ставка часа мастера оказалась заметно ниже целевой.</p><ul><li><strong>Что происходит:</strong> прибыль мастерской съедена сложными ручными операциями (например, мелким седельным швом с шагом 3.0 мм или сложной обработкой торцов).</li><li><strong>Что делать:</strong> упрощать технологию сборки либо вводить наценку за индивидуальную кастомизацию.</li></ul><h3 id="🟢-3-здоровыи-ремесленныи-заказ" tabindex="-1">🟢 3. Здоровый ремесленный заказ <a class="header-anchor" href="#🟢-3-здоровыи-ремесленныи-заказ" aria-label="Permalink to &quot;🟢 3. Здоровый ремесленный заказ&quot;">​</a></h3><p>Изделие полностью покрывает все материалы, окупает обрезки, компенсирует амортизацию оборудования, оплачивает труд мастера по желаемой ставке и оставляет мастерской чистую прибыль от 20% цены.</p><hr><h2 id="📖-откуда-берутся-цифры-3-главные-финансовые-ловушки-мастера" tabindex="-1">📖 Откуда берутся цифры: 3 главные финансовые ловушки мастера <a class="header-anchor" href="#📖-откуда-берутся-цифры-3-главные-финансовые-ловушки-мастера" aria-label="Permalink to &quot;📖 Откуда берутся цифры: 3 главные финансовые ловушки мастера&quot;">​</a></h2><p>Каждый второй мастер в кожевенном ремесле сталкивается с парадоксом: <strong>«Заказов много, за верстаком сижу до ночи, а денег в кармане к концу месяца почему-то нет»</strong>.</p><p>Вы берёте заказ на лонггер за 6 500 рублей. В голове быстрый подсчёт: <em>«Кожи ушло на 500 рублей, молния и кнопки — ещё рублей 500. Итого затрат тысяча, пять с половиной тысяч заработал!»</em></p><p>Это опасное заблуждение называется <strong>иллюзией прибыли</strong>. В реальном производстве такой кошелёк часто приносит мастеру скрытый убыток или оплачивает его ювелирный труд по ставке ниже неквалифицированного разнорабочего.</p><p>Разберём подробную методику, на которой построен калькулятор выше.</p><h3 id="🕳️-ловушка-no-1-полезная-площадь-шкуры-и-налог-на-обрезки" tabindex="-1">🕳️ Ловушка № 1. Полезная площадь шкуры и налог на обрезки <a class="header-anchor" href="#🕳️-ловушка-no-1-полезная-площадь-шкуры-и-налог-на-обрезки" aria-label="Permalink to &quot;🕳️ Ловушка № 1. Полезная площадь шкуры и налог на обрезки&quot;">​</a></h3><p>Кожа в магазинах продаётся дециметрами или квадратными метрами. Но шкура животного — это не рулон ткани и не лист фанеры правильной прямоугольной формы.</p><p>У любой шкуры есть естественная топография:</p><ol><li><strong>Полы (брюшная часть):</strong> рыхлые, сильно тянутся в одну сторону, не держат форму и не подходят для лицевых деталей кошелька или ремня.</li><li><strong>Вороток:</strong> плотный, но часто покрыт глубокими морщинами и складками.</li><li><strong>Чепрак:</strong> самый ценный и плотный участок спины.</li><li><strong>Пороки и дефекты:</strong> следы укусов оводов, шрамы от колючей проволоки, царапины, неравномерный прокрас или клейма фермы.</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   ТОПОГРАФИЯ ПОЛУКОЖИ                    │</span></span>
<span class="line"><span>├───────────────┬──────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Вороток (20%) │ Чепрак — лучшая часть (50%)              │</span></span>
<span class="line"><span>│ (морщины)     │ (лицевые детали, ремни, кошельки)        │</span></span>
<span class="line"><span>├───────────────┴──────────────────────────────────────────┤</span></span>
<span class="line"><span>│ Полы — рыхлый край, тянется (30%)                        │</span></span>
<span class="line"><span>│ (внутренние незаметные подклады или мелкие обрезки)      │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>Когда вы вырезаете детали изделия, между лекалами неизбежно остаются пустоты. Даже при идеальной ручной раскладке невозможно заполнить шкуру на 100%.</p><p>В профессиональном кожевенном производстве используется показатель <strong>коэффициента полезного раскроя (КПИ)</strong>:</p><ul><li><strong>65%–70%</strong> — для целых полукож с полами и воротком со сложной геометрией лекал;</li><li><strong>75%–80%</strong> — для качественного ровного сырья или плотной раскладки прямоугольных деталей;</li><li><strong>85%</strong> — предельный максимум при раскрое отборного чепрака на прямые ременные полосы.</li></ul><h4 id="что-это-значит-в-рублях" tabindex="-1">Что это значит в рублях? <a class="header-anchor" href="#что-это-значит-в-рублях" aria-label="Permalink to &quot;Что это значит в рублях?&quot;">​</a></h4><p>Если сумма площадей всех выкроек вашего кошелька составляет <strong>8.5 дм²</strong>, а средний раскрой полукожи — <strong>75%</strong>, то фактически на кошелёк ушло:</p><p>$$\\text{Фактический расход} = \\frac{8.5\\text{ дм²}}{0.75} = 11.33\\text{ дм²}$$</p><p>При цене кожи <strong>65 ₽ за 1 дм²</strong>:</p><ul><li>«Чистая» кожа по лекалам стоит: $8.5 \\times 65 = 552.5\\text{ ₽}$</li><li>Реально ушедшая кожа стоит: $11.33 \\times 65 = 736.7\\text{ ₽}$</li><li><strong>Разница: почти 185 рублей на одном изделии улетает в коробку с обрезками.</strong></li></ul><p>Вы оплатили эту обрезь из собственного кармана в чеке поставщика. Если не закладывать коэффициент раскроя в цену, вы буквально дарите эти деньги заказчику.</p><hr><h3 id="⏳-ловушка-no-2-норма-час-почему-вы-работаете-бесплатно" tabindex="-1">⏳ Ловушка № 2. Норма-час: почему вы работаете бесплатно <a class="header-anchor" href="#⏳-ловушка-no-2-норма-час-почему-вы-работаете-бесплатно" aria-label="Permalink to &quot;⏳ Ловушка № 2. Норма-час: почему вы работаете бесплатно&quot;">​</a></h3><p>Вторая ошибка — воспринимать все деньги, оставшиеся после покупки материалов, как свою чистую прибыль.</p><p>Ремесло мастера — это штучный ручной труд. Если вы потратили на раскрой, шерфование, склейку, седельный шов, обработку уреза и полировку <strong>6.5 часов чистого времени</strong>, ваш труд должен быть оплачен.</p><p>В бизнесе зарплата мастера и прибыль мастерской — это <strong>две разные статьи</strong>:</p><ol><li><strong>Зарплата мастера (норма-час):</strong> это компенсация вашего времени, физических сил, зрения и квалификации. Если бы вы наняли подмастерье для сборки этого кошелька, вы обязаны были бы заплатить ему эту сумму.</li><li><strong>Чистая прибыль мастерской:</strong> деньги сверх зарплаты, которые остаются на развитие бизнеса, покупку нового оборудования, аренду и компенсацию предпринимательского риска.</li></ol><p>Если после вычета кожи и фурнитуры от цены кошелька остаётся 2 500 рублей за 6.5 часов работы, то фактическая ставка вашего труда составляет <strong>~385 рублей в час</strong>. Никакой прибыли бизнесу в этом случае заказ не принёс — мастер просто поработал за скромную сдельную ставку.</p><hr><h3 id="🧰-ловушка-no-3-невидимыи-расход-фурнитура-химия-и-амортизация" tabindex="-1">🧰 Ловушка № 3. Невидимый расход: фурнитура, химия и амортизация <a class="header-anchor" href="#🧰-ловушка-no-3-невидимыи-расход-фурнитура-химия-и-амортизация" aria-label="Permalink to &quot;🧰 Ловушка № 3. Невидимый расход: фурнитура, химия и амортизация&quot;">​</a></h3><p>Помимо кожи в кошельке участвует десяток позиций, которые редко считают поштучно:</p><ul><li>Металлическая молния и бегунок;</li><li>Кнопки или скрытые магниты;</li><li>Вощёная нить и армирующий материал;</li><li>Расход химии: обувной клей, средство для полировки уреза, финишный крем или воск;</li><li>Брендовая упаковка: крафтовая коробка, бумага тишью, бирка мастерской.</li></ul><p>Кроме того, инструмент изнашивается. Пробойники со временем тупятся и требуют заточки или замены зубьев, лезвия ножей и скальпелей меняются регулярно, наждачная бумага расходуется метрами, а раскройный мат прорезается до основания.</p><p>Адекватная ставка амортизации ручного инструмента и мелких расходников составляет <strong>от 30 до 50 рублей на каждый час работы мастера</strong>. На кошельке длительностью 6.5 часов это ещё <strong>260 рублей</strong>.</p><hr><h2 id="📥-скачаите-готовыи-шаблон-таблицы-excel-для-расчета-себестоимости" tabindex="-1">📥 Скачайте готовый шаблон таблицы Excel для расчёта себестоимости <a class="header-anchor" href="#📥-скачаите-готовыи-шаблон-таблицы-excel-для-расчета-себестоимости" aria-label="Permalink to &quot;📥 Скачайте готовый шаблон таблицы Excel для расчёта себестоимости&quot;">​</a></h2><p>Для удобной работы на компьютере без интернета мы собрали этот расчёт в виде брендированного Excel-файла (<code>.xlsx</code>). Скачайте бесплатный шаблон таблицы Excel для расчёта себестоимости изделий и настройте формулы под свою мастерскую.</p><p>В файле:</p><ul><li>Полная табличная структура со всеми зашитыми формулами расчёта себестоимости;</li><li>Наглядное зонирование (голубые ячейки для ввода, серые — защищённые константы);</li><li>Выделенная строка скрытых потерь на обрезках кожи и материалов;</li><li>Автоматический светофор с диагнозом прибыльности заказа;</li><li>Защита от случайного повреждения расчётных формул.</li></ul><div class="download-banner"><div class="download-info"><div class="download-title">Бесплатный шаблон таблицы Excel для расчёта себестоимости (.xlsx)</div><div class="download-desc">Формат электронных таблиц Excel. Размер 10 КБ. Без макросов.</div></div><a href="/downloads/omnicraft_leather_cost_calculator.xlsx" download class="vp-button brand" data-omni-event="calc_article_download_xlsx"> 📥 Скачать бесплатно </a></div><hr><h2 id="📚-связанные-материалы-производственного-кластера" tabindex="-1">📚 Связанные материалы производственного кластера <a class="header-anchor" href="#📚-связанные-материалы-производственного-кластера" aria-label="Permalink to &quot;📚 Связанные материалы производственного кластера&quot;">​</a></h2><ul><li>📈 <strong><a href="/ru/articles/pricing-and-margins">Ценообразование, наценка и маржа: как рассчитать цену изделия от себестоимости</a></strong> — пошаговый разбор формул розничной и оптовой цены, критической разницы между торговой наценкой и маржой, а также расчёт точки безубыточности мастерской.</li><li>💻 <strong><a href="/ru/articles/cost-calculation-software">Программы для расчёта себестоимости: почему Excel и 1С не подходят малым мастерским</a></strong> — объективное сравнение инструментов учёта: от рукописных блокнотов и таблиц Excel до специализированных локальных систем.</li></ul><hr><h2 id="🚀-почему-excel-—-это-только-первыи-шаг" tabindex="-1">🚀 Почему Excel — это только первый шаг? <a class="header-anchor" href="#🚀-почему-excel-—-это-только-первыи-шаг" aria-label="Permalink to &quot;🚀 Почему Excel — это только первый шаг?&quot;">​</a></h2><p>Таблицы Excel — отличный инструмент для того, чтобы впервые открыть глаза на экономику и перестать работать вслепую. Но по мере роста мастерской они неизбежно упираются в потолок:</p><ol><li><strong>В таблицах нет сквозного склада:</strong> остатки полукож в дециметрах приходится вручную пересчитывать после каждого раскроя.</li><li><strong>Таблицы ломаются при росте:</strong> когда у вас 15–20 заказов в месяц, легко запутаться в версиях файлов и забыть, под какой заказ зарезервирована молния или чепрак.</li><li><strong>Нет верстака и связи с клиентами:</strong> сложно отследить статус готовности, долги заказчиков и реальное движение денег в кассе.</li></ol><p>Именно поэтому мы разработали <strong>OmniCraft ERP</strong> — профессиональную локальную программу для кожевников и ремесленных мастерских:</p><ul><li><strong>Умный учёт кожи:</strong> списание полукож по полезной площади с учётом обрезков;</li><li><strong>Калькулятор рецептов:</strong> автоматический расчёт себестоимости и резервирование материалов прямо при оформлении заказа;</li><li><strong>Интерактивный верстак:</strong> контроль этапов производства в реальном времени;</li><li><strong>Полная автономность:</strong> программа работает офлайн на вашем компьютере под Windows. Ваши данные, коммерческая тайна и база клиентов принадлежат только вам.</li></ul><div class="cta-erp-box"><div class="cta-erp-content"><h3>Попробуйте профессиональный учёт мастерской</h3><p>Скачайте бесплатную версию OmniCraft ERP для Windows и наведите порядок на верстаке и складе уже сегодня.</p><a href="/ru/" class="vp-button brand" data-omni-event="calc_article_cta_home"> Узнать больше о программе → </a></div></div>`,60))])}const _=t(c,[["render",d]]);export{f as __pageData,_ as default};
